<?php
require_once __DIR__.'/helpers.php';
$id=(int)($_GET['id']??0); $stmt=$pdo->prepare("SELECT * FROM finance_accounts WHERE id=:id");$stmt->execute([':id'=>$id]);$account=$stmt->fetch(PDO::FETCH_ASSOC);if(!$account)redirect('pages/finance/accounts.php?error=Akun tidak ditemukan');
$q=trim($_GET['q']??'');$params=[':id'=>$id];$where="t.account_id=:id AND t.posting_mode='posted'";if($q!==''){$where.=' AND (t.transaction_code LIKE :q_code OR t.transaction_name LIKE :q_name OR t.description LIKE :q_description OR t.reference_code LIKE :q_reference)';$value='%'.$q.'%';$params[':q_code']=$value;$params[':q_name']=$value;$params[':q_description']=$value;$params[':q_reference']=$value;}
$stmt=$pdo->prepare("SELECT t.*,c.category_name,p.project_name FROM transactions t LEFT JOIN transaction_categories c ON c.id=t.category_id LEFT JOIN projects p ON p.id=t.project_id WHERE $where ORDER BY t.transaction_date DESC,t.id DESC");$stmt->execute($params);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$op=$pdo->prepare("SELECT m.*,f.person_name FROM operational_fund_movements m JOIN operational_funds f ON f.id=m.fund_id WHERE m.account_id=:id AND m.movement_type IN ('receive','return') AND m.posting_mode='posted' ORDER BY m.movement_date DESC,m.id DESC");$op->execute([':id'=>$id]);$movements=$op->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Mutasi Akun - Nukari';require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';
?>
<main class="main-content"><div class="page-header d-flex justify-content-between"><div><h1 class="fw-bold mb-1"><?= f_e($account['account_name']); ?></h1><p class="text-muted mb-0">Mutasi lengkap rekening · Saldo <?= rupiah($account['current_balance']); ?></p></div><a href="<?= base_url('pages/finance/accounts.php'); ?>" class="btn btn-outline-success">Kembali</a></div>
<div class="panel mb-4"><form class="d-flex gap-2"><input type="hidden" name="id" value="<?= $id; ?>"><input name="q" value="<?= f_e($q); ?>" class="form-control" placeholder="Cari kode, referensi, atau deskripsi..."><button class="btn btn-outline-success"><i class="bi bi-search"></i></button></form></div>
<div class="panel mb-4"><h5 class="fw-bold mb-3">Transaksi Buku Kas</h5><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Tanggal</th><th>Kode</th><th>Nama Transaksi</th><th>Project</th><th class="text-end">Mutasi</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= date('d M Y',strtotime($r['transaction_date'])); ?></td><td><?= f_e($r['reference_code']?:$r['transaction_code']); ?><br><small class="text-muted">Sistem: <?=f_e($r['transaction_code']);?></small></td><td><b><?= f_e($r['transaction_name']?:$r['description']?:'-'); ?></b><br><small class="text-muted"><?=f_e($r['description']?:'-');?></small></td><td><?= f_e($r['project_name']?:'-'); ?></td><td class="text-end fw-bold <?= $r['type']==='income'?'text-success':'text-danger'; ?>"><?= $r['type']==='income'?'+':'-'; ?> <?= rupiah($r['amount']); ?></td><td><a class="btn btn-sm btn-outline-success" href="<?= base_url('pages/finance/transaction_detail.php?id='.$r['id']); ?>">Detail</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="text-center text-muted py-4">Tidak ada transaksi.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="panel"><h5 class="fw-bold mb-3">Transfer Dana Operasional</h5><div class="table-responsive"><table class="table"><thead><tr><th>Tanggal</th><th>PIC</th><th>Keterangan</th><th class="text-end">Mutasi</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?= date('d M Y',strtotime($m['movement_date'])); ?></td><td><?= f_e($m['person_name']); ?></td><td><?= f_e($m['description']); ?></td><td class="text-end fw-bold <?= $m['movement_type']==='return'?'text-success':'text-danger'; ?>"><?= $m['movement_type']==='return'?'+':'-'; ?> <?= rupiah($m['amount']); ?></td></tr><?php endforeach; ?><?php if(!$movements): ?><tr><td colspan="4" class="text-center text-muted">Tidak ada mutasi dana operasional.</td></tr><?php endif; ?></tbody></table></div></div></main>
<?php require_once __DIR__.'/../../includes/footer.php'; ?>
